import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  interpolateColors,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOrbitron = makeLoadFont('Orbitron');
const loadRajdhani = makeLoadFont('Rajdhani');

// Load fonts at module level
const { fontFamily: orbitronFamily } = loadOrbitron();
const { fontFamily: rajdhaniFamily } = loadRajdhani();

// Circuit Track Component to draw animated signals
const CircuitTrack: React.FC<{
  d: string;
  color: string;
  frame: number;
  speed: number;
}> = ({ d, color, frame, speed }) => {
  const signalOffset = -frame * (4 + speed * 0.08);

  return (
    <g>
      {/* Base Circuit Line */}
      <path
        d={d}
        fill="none"
        stroke={color}
        strokeWidth="2.5"
        opacity="0.12"
      />
      {/* Animated Glowing Signal */}
      <path
        d={d}
        fill="none"
        stroke={color}
        strokeWidth="3.5"
        strokeDasharray="50 200"
        strokeDashoffset={signalOffset}
        opacity="0.8"
        style={{
          filter: `drop-shadow(0 0 8px ${color})`,
          transition: "none",
        }}
      />
    </g>
  );
};



export type ComputerLoadAnimationProps = Record<string, any>;

const ComputerLoadAnimation: React.FC<ComputerLoadAnimationProps> = ({
  backgroundColor = "#03050a",
  transparentBackground = false,
  durationInSeconds = 8,
  maxClockSpeedMHz = 5200,
  accentColorBlue = "#00bfff",
  accentColorRed = "#ff3300",
  glowIntensity = 1,
  cameraShakeEnabled = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // --- Speed Acceleration Curve & Calculation ---
  // Speed starts low, accelerates steadily, and hits dynamic MAX overload at the end
  let baseSpeed = 15;
  if (frame < durationInFrames * 0.15) {
    baseSpeed = interpolate(frame, [0, durationInFrames * 0.15], [15, 25], {
      extrapolateRight: "clamp",
    });
  } else if (frame < durationInFrames * 0.55) {
    baseSpeed = interpolate(
      frame,
      [durationInFrames * 0.15, durationInFrames * 0.55],
      [25, 72],
      { extrapolateRight: "clamp" }
    );
  } else if (frame < durationInFrames * 0.8) {
    baseSpeed = interpolate(
      frame,
      [durationInFrames * 0.55, durationInFrames * 0.8],
      [72, 98],
      { extrapolateRight: "clamp" }
    );
  } else {
    // Fluctuates around peak performance (MAX)
    const wave = Math.sin((frame - durationInFrames * 0.8) * 0.8) * 1.5;
    baseSpeed =
      interpolate(
        frame,
        [durationInFrames * 0.8, durationInFrames],
        [98, 99.2],
        { extrapolateRight: "clamp" }
      ) + wave;
  }

  // Inject tiny high-frequency micro-jitter
  const speedJitter = (random(`jitter-${frame}`) - 0.5) * 1.2;
  const currentSpeedPercent = Math.min(100, Math.max(0, baseSpeed + speedJitter));

  // --- Dynamic Camera Shake ---
  const shakeIntensity =
    cameraShakeEnabled && currentSpeedPercent > 75
      ? interpolate(currentSpeedPercent, [75, 100], [0, 7], {
          extrapolateLeft: "clamp",
        })
      : 0;

  const shakeX = shakeIntensity > 0 ? (random(`shakex-${frame}`) - 0.5) * shakeIntensity : 0;
  const shakeY = shakeIntensity > 0 ? (random(`shakey-${frame}`) - 0.5) * shakeIntensity : 0;
  const shakeRotate =
    shakeIntensity > 0 ? (random(`shaker-${frame}`) - 0.5) * shakeIntensity * 0.15 : 0;

  // --- Colors and Glow States ---
  const dynamicAccentColor = interpolateColors(
    currentSpeedPercent / 100,
    [0, 0.5, 0.85, 1],
    [accentColorBlue, "#ff9000", accentColorRed, accentColorRed]
  );

  const ambientBlueGlow = interpolate(currentSpeedPercent, [0, 100], [0.15, 0.45]);
  const ambientRedGlow = interpolate(currentSpeedPercent, [0, 100], [0.05, 0.8]);

  // --- Dynamic Speed Streaks / Particles ---
  const speedStreaks = Array.from({ length: 14 }).map((_, i) => {
    const seed = i * 245.89;
    const side = i % 2 === 0 ? "left" : "right";
    const yPos = 150 + (seed % (height - 300));
    const baseLength = 70 + (seed % 90);

    const speedFactor = interpolate(currentSpeedPercent, [0, 100], [0.4, 3.2]);
    const length = baseLength * speedFactor;

    // Fast travel offset
    const travelRange = side === "left" ? [-250, width + 250] : [width + 250, -250];
    const offset = (frame * 15 + seed) % (width + 500);
    const posX =
      side === "left"
        ? travelRange[0] + offset * (speedFactor * 0.8)
        : travelRange[0] - offset * (speedFactor * 0.8);

    const color = side === "left" ? accentColorBlue : accentColorRed;
    const opacity = interpolate(currentSpeedPercent, [10, 80], [0.05, 0.65]);

    return (
      <div
        key={`streak-${i}`}
        style={{
          position: "absolute",
          left: posX,
          top: yPos,
          width: length,
          height: 3 + (seed % 3),
          background: `linear-gradient(to ${side === "left" ? "right" : "left"}, rgba(255,255,255,0), ${color})`,
          borderRadius: "4px",
          boxShadow: `0 0 ${10 * glowIntensity}px ${color}`,
          opacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    );
  });

  // --- Speedometer Ticks Calculator ---
  const totalTicks = 45;
  const gaugeRadius = 290;
  const ticksList = [];

  for (let i = 0; i < totalTicks; i++) {
    const percentOfTicks = i / (totalTicks - 1);
    // Starts at -120deg (bottom-left) to +120deg (bottom-right)
    const tickAngle = -120 + percentOfTicks * 240;
    // Map tick angle to standard trigonometric unit circle coordinates (-90deg offset)
    const angleInRad = ((tickAngle - 90) * Math.PI) / 180;

    let tickColor = accentColorBlue;
    if (percentOfTicks > 0.75) {
      tickColor = accentColorRed;
    } else if (percentOfTicks > 0.45) {
      tickColor = "#ff9000";
    }

    const isActive = percentOfTicks <= currentSpeedPercent / 100;
    const opacity = isActive ? 1.0 : 0.15;
    const strokeWidth = i % 5 === 0 ? 3.5 : 1.5;
    const tickLen = i % 5 === 0 ? 18 : 10;

    // SVG coordinate space of Speedometer is 800x800, center is 400, 400
    const outerX = 400 + Math.cos(angleInRad) * gaugeRadius;
    const outerY = 400 + Math.sin(angleInRad) * gaugeRadius;
    const innerX = 400 + Math.cos(angleInRad) * (gaugeRadius - tickLen);
    const innerY = 400 + Math.sin(angleInRad) * (gaugeRadius - tickLen);

    ticksList.push(
      <line
        key={`tick-${i}`}
        x1={innerX}
        y1={innerY}
        x2={outerX}
        y2={outerY}
        stroke={tickColor}
        strokeWidth={strokeWidth}
        opacity={opacity}
        style={{
          filter: isActive
            ? `drop-shadow(0 0 ${5 * glowIntensity}px ${tickColor})`
            : "none",
          transition: "none",
        }}
      />
    );
  }

  // Needle Rotations
  const needleAngle = -120 + (currentSpeedPercent / 100) * 240;

  // --- LOAD Microchip Design ---
  // Chip base sizing & proportions
  const chipWidth = width * 0.74;
  const chipHeight = height * 0.22;

  // Left & Right pins
  const pinCount = 10;
  const pinsLeft = Array.from({ length: pinCount }).map((_, i) => (
    <div
      key={`pin-l-${i}`}
      style={{
        position: "absolute",
        left: -18,
        top: `${14 + i * 8}%`,
        width: 18,
        height: 6,
        background: "linear-gradient(to right, #4b5563, #9ca3af, #1f2937)",
        borderRadius: "2px 0 0 2px",
        boxShadow: "0 1px 3px rgba(0,0,0,0.6)",
        transition: "none",
      }}
    />
  ));

  const pinsRight = Array.from({ length: pinCount }).map((_, i) => (
    <div
      key={`pin-r-${i}`}
      style={{
        position: "absolute",
        right: -18,
        top: `${14 + i * 8}%`,
        width: 18,
        height: 6,
        background: "linear-gradient(to left, #4b5563, #9ca3af, #1f2937)",
        borderRadius: "0 2px 2px 0",
        boxShadow: "0 1px 3px rgba(0,0,0,0.6)",
        transition: "none",
      }}
    />
  ));

  // Dynamic vertical bars inside microchip LOAD screen
  const totalBars = 12;
  const loadBars = Array.from({ length: totalBars }).map((_, i) => {
    const fraction = i / (totalBars - 1);
    const isActive = fraction <= currentSpeedPercent / 100;
    const barHeight = 25 + fraction * 60; // Ascending visual steps

    const barColor = interpolateColors(fraction, [0, 0.5, 1], [accentColorBlue, "#ff9000", accentColorRed]);

    return (
      <div
        key={`load-bar-${i}`}
        style={{
          width: 15,
          height: barHeight,
          backgroundColor: isActive ? barColor : "rgba(255, 255, 255, 0.08)",
          borderRadius: "3px 3px 1px 1px",
          boxShadow: isActive ? `0 0 ${12 * glowIntensity}px ${barColor}` : "none",
          transition: "none",
        }}
      />
    );
  });

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "space-between",
        paddingTop: height * 0.06,
        paddingBottom: height * 0.05,
        transform: `translate(${shakeX}px, ${shakeY}px) rotate(${shakeRotate}deg)`,
        transition: "none",
      }}
    >
      {/* Ambient Neon Atmosphere (Motion Graphics Backglows) */}
      <div
        style={{
          position: "absolute",
          left: "-15%",
          top: "15%",
          width: "50%",
          height: "55%",
          borderRadius: "50%",
          background: accentColorBlue,
          filter: "blur(150px)",
          opacity: ambientBlueGlow,
          pointerEvents: "none",
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          right: "-15%",
          top: "15%",
          width: "50%",
          height: "55%",
          borderRadius: "50%",
          background: accentColorRed,
          filter: "blur(150px)",
          opacity: ambientRedGlow,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Cybernetic Circuit Board Network (Background) */}
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          top: 0,
          left: 0,
          pointerEvents: "none",
        }}
        viewBox="0 0 1080 1920"
      >
        <CircuitTrack
          d="M 120,250 L 320,250 L 380,310 L 380,550"
          color={accentColorBlue}
          frame={frame}
          speed={currentSpeedPercent}
        />
        <CircuitTrack
          d="M 80,1550 L 250,1550 L 350,1450 L 350,1180"
          color={accentColorBlue}
          frame={frame}
          speed={currentSpeedPercent}
        />
        <CircuitTrack
          d="M 960,300 L 780,300 L 720,360 L 720,580"
          color={accentColorRed}
          frame={frame}
          speed={currentSpeedPercent}
        />
        <CircuitTrack
          d="M 1000,1650 L 820,1650 L 720,1550 L 720,1180"
          color={accentColorRed}
          frame={frame}
          speed={currentSpeedPercent}
        />
        <CircuitTrack
          d="M 60,960 L 300,960 L 390,1050 L 390,1220"
          color={accentColorBlue}
          frame={frame}
          speed={currentSpeedPercent}
        />
        <CircuitTrack
          d="M 1020,960 L 780,960 L 690,1050 L 690,1220"
          color={accentColorRed}
          frame={frame}
          speed={currentSpeedPercent}
        />
      </svg>

      {/* Fast Motion Streaks */}
      {speedStreaks}

      {/* ================= GAUGE COMPONENT (TOP) ================= */}
      <div
        style={{
          position: "relative",
          width: 660,
          height: 660,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
          marginTop: height * 0.03,
        }}
      >
        {/* Outer Circular Ring and Bezel styling */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            background: "radial-gradient(circle, #0c0f17 30%, #040609 100%)",
            border: `6px solid #1c273a`,
            boxShadow: `0 10px 40px rgba(0,0,0,0.85), inset 0 0 35px rgba(0,0,0,0.9), 0 0 ${25 * glowIntensity}px ${dynamicAccentColor}22`,
            transition: "none",
          }}
        />

        {/* Speedometer SVG Face (Ticks & Sub Arcs) */}
        <svg
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            top: 0,
            left: 0,
            pointerEvents: "none",
          }}
          viewBox="0 0 800 800"
        >
          {/* Circular inner guides */}
          <circle
            cx="400"
            cy="400"
            r="305"
            fill="none"
            stroke="#162238"
            strokeWidth="2.5"
            opacity="0.8"
          />
          <circle
            cx="400"
            cy="400"
            r="265"
            fill="none"
            stroke="#101826"
            strokeWidth="1.5"
          />
          {ticksList}
        </svg>

        {/* Dynamic Needle Pinwheel */}
        <div
          style={{
            position: "absolute",
            width: 8,
            height: 260,
            bottom: "50%",
            left: "calc(50% - 4px)",
            background: `linear-gradient(to top, ${accentColorRed}, #ffffff)`,
            transformOrigin: "bottom center",
            transform: `rotate(${needleAngle}deg)`,
            borderRadius: "4px",
            boxShadow: `0 0 ${16 * glowIntensity}px ${accentColorRed}`,
            zIndex: 5,
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* Central Bezel Cap */}
        <div
          style={{
            position: "absolute",
            width: 72,
            height: 72,
            borderRadius: "50%",
            background: "radial-gradient(circle, #3b4960 0%, #0d121c 100%)",
            border: "5px solid #05070a",
            boxShadow: "0 6px 15px rgba(0,0,0,0.85), inset 0 2px 4px rgba(255,255,255,0.25)",
            zIndex: 6,
            transition: "none",
          }}
        />

        {/* Digital Speed HUD Display */}
        <div
          style={{
            position: "absolute",
            top: "34%",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            pointerEvents: "none",
            zIndex: 4,
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: orbitronFamily,
              fontSize: 22,
              color: "#859bb8",
              letterSpacing: 4,
              marginBottom: 2,
              fontWeight: 600,
            }}
          >
            SPEED
          </span>
          <span
            style={{
              fontFamily: orbitronFamily,
              fontSize: 88,
              fontWeight: 900,
              color: "#ffffff",
              textShadow: `0 0 ${20 * glowIntensity}px ${currentSpeedPercent > 80 ? accentColorRed : accentColorBlue}`,
              lineHeight: 1,
            }}
          >
            {Math.floor((currentSpeedPercent / 100) * maxClockSpeedMHz)}
          </span>
          <span
            style={{
              fontFamily: rajdhaniFamily,
              fontSize: 24,
              color: currentSpeedPercent > 80 ? accentColorRed : accentColorBlue,
              fontWeight: "bold",
              letterSpacing: 3,
              marginTop: 4,
            }}
          >
            MHz
          </span>
        </div>

        {/* Dynamic Status Text (MAX Overload alerts) */}
        <div
          style={{
            position: "absolute",
            bottom: "18%",
            fontFamily: orbitronFamily,
            fontSize: 24,
            fontWeight: 800,
            color: dynamicAccentColor,
            textShadow: `0 0 ${12 * glowIntensity}px ${dynamicAccentColor}`,
            letterSpacing: 3,
            zIndex: 4,
            transition: "none",
            animation: currentSpeedPercent > 85 ? "pulse 0.2s infinite alternate" : "none",
          }}
        >
          {currentSpeedPercent > 85 ? "MAX OVERLOAD" : currentSpeedPercent > 50 ? "TURBO BOOST" : "SYSTEM IDLE"}
        </div>
      </div>

      {/* ================= 3D MICROCHIP COMPONENT (BOTTOM) ================= */}
      <div
        style={{
          position: "relative",
          width: chipWidth,
          height: chipHeight,
          transform: `perspective(1200px) rotateX(34deg) rotateY(0deg) translate3d(0, 0, 0)`,
          transformStyle: "preserve-3d",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          marginBottom: height * 0.04,
          transition: "none",
        }}
      >
        {/* Shadow and Base Glow underneath the chip */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            background: "transparent",
            borderRadius: 16,
            transform: "translateZ(-15px)",
            boxShadow: `0 15px 45px rgba(0,0,0,0.95), 0 0 ${40 * glowIntensity}px ${dynamicAccentColor}55`,
            transition: "none",
          }}
        />

        {/* Silicon Base Plate */}
        <div
          style={{
            position: "relative",
            width: "100%",
            height: "100%",
            backgroundColor: "#0a0d14",
            borderRadius: 18,
            border: `3.5px solid #1d2636`,
            boxShadow: "inset 0 0 25px rgba(0,0,0,0.9)",
            transformStyle: "preserve-3d",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            padding: "20px 30px",
            transition: "none",
          }}
        >
          {/* Metal Contact Pins */}
          {pinsLeft}
          {pinsRight}

          {/* Glowing under-rim light */}
          <div
            style={{
              position: "absolute",
              bottom: -4,
              left: "8%",
              width: "84%",
              height: 6,
              background: `linear-gradient(to right, transparent, ${dynamicAccentColor}, transparent)`,
              boxShadow: `0 0 ${16 * glowIntensity}px ${dynamicAccentColor}`,
              borderRadius: "4px",
              opacity: interpolate(currentSpeedPercent, [0, 100], [0.3, 1]),
              transition: "none",
            }}
          />

          {/* Inside Microchip Screen */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              width: "100%",
              marginBottom: 12,
              paddingLeft: 4,
              paddingRight: 4,
              transition: "none",
            }}
          >
            <span
              style={{
                fontFamily: orbitronFamily,
                fontSize: 26,
                fontWeight: 900,
                color: "#9ca3af",
                letterSpacing: 3,
                textShadow: "0 2px 4px rgba(0,0,0,0.5)",
              }}
            >
              LOAD
            </span>
            <span
              style={{
                fontFamily: orbitronFamily,
                fontSize: 28,
                fontWeight: "bold",
                color: dynamicAccentColor,
                textShadow: `0 0 ${10 * glowIntensity}px ${dynamicAccentColor}`,
              }}
            >
              {currentSpeedPercent.toFixed(1)}%
            </span>
          </div>

          {/* Bar Chart Panel */}
          <div
            style={{
              display: "flex",
              alignItems: "flex-end",
              justifyContent: "space-between",
              width: "100%",
              height: 105,
              backgroundColor: "#030407",
              border: "2px solid #131924",
              borderRadius: 10,
              padding: "10px 18px",
              boxShadow: "inset 0 0 15px rgba(0,0,0,0.95)",
              transition: "none",
            }}
          >
            {loadBars}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComputerLoadAnimation;